function staticHtml(page, type = 'Article') {
  const canonical = `${SITE_URL}/${page.path}`;
  const title = `${page.title}｜${SITE_NAME}`;
  const schema = {
    '@context': 'https://schema.org', '@graph': [
      { '@type': type, headline: page.title, name: page.title, description: page.description, url: canonical, inLanguage: 'ja', mainEntityOfPage: canonical, datePublished: '2026-08-10', dateModified: UPDATED, ...(type === 'WebApplication' ? { applicationCategory: 'LifestyleApplication', operatingSystem: 'Web', isAccessibleForFree: true, offers: { '@type': 'Offer', price: '0', priceCurrency: 'JPY' } } : {}), author: { '@type': 'Organization', '@id': `${SITE_URL}/#editorial`, name: 'Fate Lab編集部', url: `${SITE_URL}/editorial-policy` }, reviewedBy: { '@type': 'Organization', name: '温齋株式会社', url: `${SITE_URL}/about` }, publisher: { '@type': 'Organization', '@id': `${SITE_URL}/#organization`, name: SITE_NAME, url: `${SITE_URL}/`, logo: { '@type': 'ImageObject', url: `${SITE_URL}/og-fate-lab.png`, width: 1200, height: 630 } }, image: { '@type': 'ImageObject', url: `${SITE_URL}/og-fate-lab.png`, width: 1200, height: 630 } },
      { '@type': 'BreadcrumbList', itemListElement: type === 'Article' ? [{ '@type': 'ListItem', position: 1, name: 'Fate Lab', item: `${SITE_URL}/` }, { '@type': 'ListItem', position: 2, name: '占い解説', item: `${SITE_URL}/guides/` }, { '@type': 'ListItem', position: 3, name: page.title, item: canonical }] : [{ '@type': 'ListItem', position: 1, name: 'Fate Lab', item: `${SITE_URL}/` }, { '@type': 'ListItem', position: 2, name: page.title, item: canonical }] }
    ]
  };
  const currentIndex = guides.findIndex(g => g.path === page.path);
  const relatedGuides = currentIndex < 0 ? guides.slice(0, 4) : Array.from({ length: Math.min(4, guides.length - 1) }, (_, offset) => guides[(currentIndex + offset + 1) % guides.length]);
  const related = relatedGuides.map(g => `<a href="/${g.path}">${escapeHtml(g.title)}</a>`).join('');
  const meta = type === 'Article' ? `<div class="meta">公開日：2026-08-10　更新日：${UPDATED}　Fate Lab編集部</div>` : '';
  const editorial = type === 'Article' ? `<details class="editorial-details"><summary>この記事の制作方針と検証について</summary><div><section class="author"><strong>制作・計算仕様の検証：Fate Lab編集部</strong><p>記事の構成整理や表現確認に生成AIを利用する場合があります。本文の各論はFate Labの鑑定エンジンが持つ解釈マスタから展開し、実装済み計算仕様と固定テストに照らして確認しています。資格者監修がない記事を専門家監修とは表示しません。</p></section><section class="sources"><strong>参考情報と検証方針</strong><ul><li>暦・天体・干支計算は、公開された暦法と実装ライブラリの固定テストで検証</li><li>境界日や出生時間の有無で結果が変わる条件を明示</li><li>占術は科学的診断ではなく、自己理解の参考情報として提供</li></ul><a href="/editorial-policy">AI利用を含む制作方針</a>　<a href="/methodology">鑑定ロジック</a></section></div></details>` : '';
  const showAffiliate = type === 'Article' ? SHOW_GUIDE_AFFILIATE : ['WebApplication', 'CollectionPage'].includes(type);
  return `<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="manifest" href="/site.webmanifest"><meta name="theme-color" content="#faf7ef"><title>${escapeHtml(title)}</title><meta name="description" content="${escapeHtml(page.description)}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><link rel="canonical" href="${canonical}"><meta property="og:type" content="${type === 'Article' ? 'article' : 'website'}"><meta property="og:locale" content="ja_JP"><meta property="og:site_name" content="Fate Lab"><meta property="og:title" content="${escapeHtml(title)}"><meta property="og:description" content="${escapeHtml(page.description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${SITE_URL}/og-fate-lab.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${SITE_URL}/og-fate-lab.png">${analytics}<style>${sharedStyle}</style><script type="application/ld+json">${JSON.stringify(schema).replace(/</g, '\\u003c')}</script></head><body><header>${nav}</header><main><div class="breadcrumb"><a href="/">Fate Lab</a> › ${type === 'Article' ? '<a href="/guides/">占い解説</a> › ' : ''}${escapeHtml(page.title)}</div><article><h1>${escapeHtml(page.title)}</h1>${meta}<p>${escapeHtml(page.description)}</p>${page.body}</article>${type === 'Article' ? `<aside class="related"><strong>関連する占い解説</strong>${related}</aside>` : ''}<a class="cta" href="/#form">生年月日を入力して無料で鑑定する</a>${editorial}${showAffiliate ? affiliateCard : ''}<p>最終更新日：${UPDATED}</p></main>${footer}</body></html>`;
}

function guideIndexHtml() {
  const page = { path: 'guides/', title: '生年月日占い・四柱推命の基礎知識', description: '四柱推命、命式、日干、五行、性格、適職、相性など、生年月日占いの基礎をFate Labが解説します。' };
  const cards = guides.map(expandedGuide).map(g => `<li><a href="/${g.path}"><strong>${escapeHtml(g.title)}</strong><span>${escapeHtml(g.description)}</span></a></li>`).join('');
  page.body = `<p>占術の計算方法、結果の読み方、注意点をテーマ別にまとめています。診断結果を決めつけに使わず、自分の経験と照らし合わせるための参考資料としてご利用ください。</p><ul class="guide-list">${cards}</ul><style>.guide-list{list-style:none;padding:0;display:grid;gap:14px}.guide-list a{display:block;padding:18px;background:#fffdf8;border:1px solid #d4c5a0;border-radius:8px;text-decoration:none}.guide-list strong,.guide-list span{display:block}.guide-list span{font-size:14px;color:#5f564c;margin-top:6px}</style>`;
  return staticHtml(page, 'CollectionPage');
}

function toolIndexHtml() {
  const page = { path: 'tools/', title: '生年月日の無料占い計算ツール', description: '日干・日柱、運命数などを生年月日から無料・登録不要で自動計算できるFate Labのツール一覧です。' };
  const cards = tools.map(tool => `<li><a href="/${tool.path}"><strong>${escapeHtml(tool.title)}</strong><span>${escapeHtml(tool.description)}</span></a></li>`).join('');
  page.body = `<p>Fate Labの鑑定エンジンで使用している計算規則を、項目ごとに確認できます。結果は自己理解の参考情報としてご利用ください。</p><ul class="tool-list">${cards}</ul><h2>計算結果について</h2><p>同じ入力条件と同じ計算バージョンでは同じ結果を返します。占術は医療・法律・金融などの専門的判断を代替しません。</p>`;
  return staticHtml(page, 'CollectionPage');
}

if (!fs.existsSync(lpPath) || !fs.existsSync(indexPath) || !fs.existsSync(topPagePath)) {
  console.error('Build output or top page source is missing');
  process.exit(1);
}

const appTemplate = fs.readFileSync(indexPath, 'utf-8');
fs.writeFileSync(path.join(distDir, 'app.html'), appTemplate);
for (const route of appRoutes) writePage(route.path, appPageHtml(appTemplate, route));
for (const guide of guides.map(expandedGuide)) writePage(guide.path, staticHtml(guide));
for (const tool of tools) writePage(tool.path, staticHtml(tool, 'WebApplication'));
for (const page of infoPages) writePage(page.path, staticHtml(page, 'WebPage'));
writePage('guides', guideIndexHtml());
writePage('tools', toolIndexHtml());
const sitemapPaths = ['','guides/','tools/', ...guides.map(page => page.path), ...tools.map(page => page.path), ...infoPages.map(page => page.path), 'privacy', 'terms', 'tokushohou'];
const sitemapXml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[...new Set(sitemapPaths)].map(route => `  <url><loc>${SITE_URL}/${route}</loc><lastmod>${UPDATED}</lastmod><changefreq>${route === '' || route.endsWith('/') ? 'weekly' : 'monthly'}</changefreq><priority>${route === '' ? '1.0' : route.startsWith('guides/angel-number') ? '0.8' : '0.7'}</priority></url>`).join('\n')}\n</urlset>\n`;
fs.writeFileSync(path.join(distDir, 'sitemap.xml'), sitemapXml);
fs.copyFileSync(topPagePath, indexPath);
console.log(`Generated SEO HTML for /, ${appRoutes.length} app routes, ${guides.length} guides, ${tools.length} tools, and ${infoPages.length} information pages`);
